[TFMDocumentType('filters')]
class TFMRequestFiltersElement extends TFMRequestElement
{
    InventLocationId	location;
    date				deliveryDate;
    str					scannedValue;
    TFMOrderTypes       orderTypes;
    boolean             initFromParmFilter;

}

Method.Source:
public TFMOrderTypes parmTfmOrderTypes(TFMOrderTypes _type = orderTypes)
{
    orderTypes = _type;
    return orderTypes;
}

public InventLocationId parmWarehouse(InventLocationId _locationId = location)
{
    location = _locationId;
    return location;
}

public Date parmDeliveryDate(Date _deliveryDate = deliveryDate)
{
    deliveryDate = _deliveryDate;
    return deliveryDate;
}

public str parmScannedValue(str _scannedValue = scannedValue)
{
    scannedValue = _scannedValue;
    return scannedValue;
}

public void new()
{
    super();        
    deliveryDate = TFMHelper::today();
}

    public TFMDocumentDeviceId parmdeviceID(TFMDocumentDeviceId _deviceId = deviceId)
    {
        TFMDocumentDeviceId ret;
        TFMDeviceTable		devices = TFMDeviceTable::FindOrCreateDevice(_deviceId);

        ret = super(_deviceId);

		if (devices.InventLocationId)
        {
            location = devices.InventLocationId;
        }

        return ret;
    }

public boolean parmInitFromParmFilter(boolean _initFromParmFilter = initFromParmFilter)
{
    initFromParmFilter = _initFromParmFilter;
    return initFromParmFilter;
}
